const headers = $json.headers || {};
const tenantId = headers["x-tenant-id"] || "default";
const documentId = headers["x-document-id"] || "new";
const knowledgeBaseId = headers["x-knowledge-base-id"] || "default";
const binaryKeys = Object.keys($binary || {});
if (binaryKeys.length === 0) {
  return [{ json: { success: false, error: "No file received" } }];
}
const binaryKey = binaryKeys[0];
const fileData = $binary[binaryKey];
const timestamp = new Date().toISOString().replace(/[:.]/g, "-");
const baseName = fileData.fileName || "document.pdf";
const driveFileName = tenantId + "/" + documentId + "/" + timestamp + "_" + baseName;
return [{
  json: {
    success: true,
    documentId: documentId,
    tenantId: tenantId,
    knowledgeBaseId: knowledgeBaseId,
    originalName: baseName,
    driveFileName: driveFileName,
    mimeType: fileData.mimeType || "application/octet-stream",
    fileSize: fileData.fileSize || 0,
    timestamp: new Date().toISOString()
  },
  binary: {
    file: {
      data: $binary[binaryKey].data,
      mimeType: fileData.mimeType || "application/octet-stream",
      fileName: baseName
    }
  }
}];

const processResult = $('2. Procesar Archivo').item.json;
const driveResult = $('3. Subir a Google Drive').item.json;
const versionResult = $('4. Guardar Version en Supabase').item.json;

return [{
  json: {
    success: true,
    documentId: processResult.documentId,
    tenantId: processResult.tenantId,
    filename: processResult.originalName,
    fileUrl: driveResult.webViewLink,
    storageProvider: 'gdrive',
    fileSize: processResult.fileSize,
    contentType: processResult.mimeType,
    version: versionResult.version_number,
    versionId: versionResult.id,
    gdriveFileId: driveResult.id,
    timestamp: new Date().toISOString(),
    message: 'Archivo subido a Google Drive y version registrada en Supabase'
  }
}];

